Read file C:\Users\RDP\swat4-android\android\app\src\main\java\fr\tibkpl\openswat4\DeviceProfile.java, lines 1-144
1: package fr.tibkpl.openswat4;
2: 
3: import android.content.Context;
4: import android.os.Build;
5: import android.util.Log;
6: 
7: import java.io.File;
8: import java.util.Locale;
9: 
10: /**
11:  * Profil de l'appareil : nature du GPU (donc pilote Vulkan utilisable dans le
12:  * runtime Linux), resolution de rendu interne et debit d'images cible.
13:  *
14:  * Le runtime embarque deux pilotes GPU :
15:  * <ul>
16:  *   <li><b>Turnip</b> (freedreno) pour les GPU Qualcomm Adreno ; il parle au
17:  *       pilote noyau KGSL d'Android, expose par <code>/dev/kgsl-3d0</code>.</li>
18:  *   <li><b>malisx2</b> pour les GPU Arm Mali ; il parle au pilote noyau
19:  *       <code>mali_kbase</code> d'Android, expose par <code>/dev/mali0</code>.</li>
20:  * </ul>
21:  * Sans pilote compatible, le rendu se fait en logiciel (Mesa llvmpipe) :
22:  * fonctionnel, mais lent.
23:  *
24:  * Les valeurs par defaut sont choisies pour que le jeu reste fluide et
25:  * stable (debit fixe grace a MinDesiredFrameRate du moteur, cf.
26:  * setup-wine.sh) sur des telephones d'entree de gamme.
27:  */
28: final class DeviceProfile {
29: 
30:     private static final String TAG = "OpenSWAT4";
31: 
32:     /** Rendu par le pilote Vulkan embarque (Adreno). */
33:     static final String RENDERER_TURNIP = "turnip";
34:     /** Rendu par le pilote Vulkan embarque (Mali). */
35:     static final String RENDERER_MALI = "mali";
36:     /** Rendu logiciel (llvmpipe). */
37:     static final String RENDERER_SOFTWARE = "software";
38: 
39:     /** Mode de rendu retenu. */
40:     final String renderer;
41:     /** Hauteur de l'ecran virtuel interne (la largeur suit le format de l'ecran). */
42:     final int renderHeight;
43:     /** Debit d'images impose au moteur (MinDesiredFrameRate). */
44:     final int targetFps;
45:     /** Nom lisible du GPU, pour l'ecran de reglages. */
46:     final String gpuName;
47: 
48:     private DeviceProfile(String renderer, int renderHeight, int targetFps, String gpuName) {
49:         this.renderer = renderer;
50:         this.renderHeight = renderHeight;
51:         this.targetFps = targetFps;
52:         this.gpuName = gpuName;
53:     }
54: 
55:     /**
56:      * Detecte le GPU et les capacites du telephone.
57:      *
58:      * @param rootfs dossier du runtime Linux deja extrait (on verifie que le
59:      *               pilote est bien present avant de l'annoncer)
60:      */
61:     static DeviceProfile detect(Context context, File rootfs) {
62:         boolean adreno = new File("/dev/kgsl-3d0").exists();
63:         boolean mali = new File("/dev/mali0").exists();
64:         String soc = socName();
65: 
66:         if (adreno && new File(rootfs, "opt/turnip/lib").isDirectory()) {
67:             return new DeviceProfile(RENDERER_TURNIP, adrenoHeight(soc), 30, "Qualcomm Adreno (" + soc + ")");
68:         }
69:         if (mali && new File(rootfs, "opt/mali/libvulkan_malisx2.so").isFile()) {
70:             return new DeviceProfile(RENDERER_MALI, maliHeight(soc), 30, "Arm Mali (" + soc + ")");
71:         }
72:         if (adreno) {
73:             // GPU Adreno mais pilote absent du runtime : on peut encore utiliser
74:             // le rendu logiciel, ou le pilote Mesa livre avec le runtime.
75:             Log.w(TAG, "GPU Adreno detecte mais Turnip absent du runtime");
76:             return new DeviceProfile(RENDERER_SOFTWARE, 540, 30, "Adreno (logiciel)");
77:         }
78:         if (mali) {
79:             Log.w(TAG, "GPU Mali detecte mais malisx2 absent du runtime");
80:             return new DeviceProfile(RENDERER_SOFTWARE, 540, 30, "Mali (logiciel)");
81:         }
82:         return new DeviceProfile(RENDERER_SOFTWARE, 540, 30, "logiciel (" + soc + ")");
83:     }
84: 
85:     /**
86:      * Hauteur de rendu pour un GPU Adreno. Les Adreno 5xx/6xx (SD660 = 512,
87:      * SD845 = 630) sont de milieu de gamme : 720p tient la route, on evite le
88:      * 1080p qui fait chuter le debit d'images de facon irreguliere.
89:      */
90:     private static int adrenoHeight(String soc) {
91:         String s = soc.toLowerCase(Locale.ROOT);
92:         if (s.contains("855") || s.contains("865") || s.contains("8gen")
93:                 || s.contains("qcom") && s.contains("8")) {
94:             return 1080;
95:         }
96:         if (s.contains("730") || s.contains("732") || s.contains("740")
97:                 || s.contains("835") || s.contains("845") || s.contains("860")
98:                 || s.contains("870") || s.contains("888")) {
99:             return 1080;
100:         }
101:         return 720;
102:     }
103: 
104:     /**
105:      * Hauteur de rendu pour un GPU Mali. Les Mali-G52 (Helio G70, 2 coeurs)
106:      * sont en dessous de la moyenne : 540p pour garder un debit stable.
107:      */
108:     private static int maliHeight(String soc) {
109:         String s = soc.toLowerCase(Locale.ROOT);
110:         if (s.contains("g57") || s.contains("g68") || s.contains("g77") || s.contains("g78")
111:                 || s.contains("g710") || s.contains("g715") || s.contains("g610")) {
112:             return 720;
113:         }
114:         return 540;
115:     }
116: 
117:     /** Identification du systeme sur puce, lisible dans les reglages. */
118:     static String socName() {
119:         String soc = "";
120:         if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
121:             soc = Build.SOC_MANUFACTURER;
122:         }
123:         if (soc == null || soc.isEmpty()) {
124:             soc = Build.HARDWARE;
125:         }
126:         return soc == null ? "" : soc;
127:     }
128: 
129:     /** Le mode de rendu demande par l'utilisateur prime sur la detection. */
130:     static String rendererFor(Context context, DeviceProfile profile, boolean gpuFailed) {
131:         if (gpuFailed) return RENDERER_SOFTWARE;
132:         String asked = GameData.getRenderer(context);
133:         if (asked == null || "auto".equals(asked)) return profile.renderer;
134:         if (RENDERER_SOFTWARE.equals(asked)) return RENDERER_SOFTWARE;
135:         // Un pilote exige explicitement n'est utilise que s'il est present.
136:         if (RENDERER_MALI.equals(asked) && RENDERER_MALI.equals(profile.renderer)) {
137:             return RENDERER_MALI;
138:         }
139:         if (RENDERER_TURNIP.equals(asked) && RENDERER_TURNIP.equals(profile.renderer)) {
140:             return RENDERER_TURNIP;
141:         }
142:         return profile.renderer;
143:     }
144: }

