package fr.tibkpl.openswat4;

import android.os.Handler;
import android.os.Looper;
import android.util.Log;

import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * Collecte d'informations de diagnostic sur l'appareil.
 *
 * <p>Objectif : comprendre pourquoi le telephone se redemarre ou pourquoi le
 * jeu ne demarre pas, sans avoir besoin d'un cable USB.  Le resultat est
 * affiche dans l'application et peut etre copie ou partage par l'utilisateur.
 *
 * <p>Les commandes sont lancees par l'application elle-meme, avec ses propres
 * droits : aucun privilege root n'est demande ni utilise.
 */
final class Diagnostics {

    private static final String TAG = "OpenSWAT4";
    /** Au-dela, on arrete la collecte : la memoire du telephone est limitee. */
    private static final int MAX_LINES = 400;

    private Diagnostics() {
    }

    /** Resultat de la collecte, affiche puis propose au partage. */
    static final class Report {
        final String text;
        Report(String text) {
            this.text = text;
        }
    }

    /**
     * Lance la collecte dans un fil separe et rend le resultat sur le fil
     * principal.
     */
    static void collect(AppCompatBridge bridge) {
        new Thread(() -> {
            StringBuilder out = new StringBuilder();
            out.append("=== Diagnostic SWAT 4 ===\n");
            out.append("app : ").append(bridge.appVersion()).append('\n');
            out.append("date : ").append(new java.util.Date()).append("\n\n");

            out.append("--- appareil ---\n");
            for (String c : new String[]{"getprop ro.product.manufacturer",
                    "getprop ro.product.model", "getprop ro.build.version.release",
                    "getprop ro.build.version.sdk", "getprop ro.product.cpu.abi",
                    "getprop ro.hardware", "getprop ro.board.platform",
                    "uname -a"}) {
                append(out, c);
            }

            out.append("\n--- memoire / stockage ---\n");
            for (String c : new String[]{"cat /proc/meminfo | head -3",
                    "df -h /data | tail -2", "ls /dev/kgsl-3d0 /dev/mali0 2>&1"}) {
                append(out, c);
            }

            out.append("\n--- journal du jeu ---\n");
            File log = bridge.gameLogFile();
            if (log != null && log.isFile()) {
                out.append(tail(log, 60));
            } else {
                out.append("(pas de fichier journal)\n");
            }

            out.append("\n--- processus SWAT / proot ---\n");
            append(out, "ps -A 2>/dev/null | grep -i -E 'proot|wine|swat' || echo '(aucun)'");

            out.append("\n--- journal Android (filtré) ---\n");
            append(out, "logcat -d -v threadtime -s OpenSWAT4:V AndroidRuntime:E libc:E DEBUG:E '*:S' 2>/dev/null | tail -60");

            bridge.deliver(new Report(out.toString()));
        }, "diagnostics").start();
    }

    /** Execute une commande et ajoute sa sortie. */
    private static void append(StringBuilder out, String command) {
        out.append("$ ").append(command).append('\n');
        Process p = null;
        try {
            p = new ProcessBuilder("sh", "-c", command).redirectErrorStream(true).start();
            String text = read(p, MAX_LINES);
            out.append(text.isEmpty() ? "(vide)\n" : text);
        } catch (IOException e) {
            out.append("(erreur : ").append(e.getMessage()).append(")\n");
        } finally {
            if (p != null) p.destroy();
        }
        out.append('\n');
    }

    private static String read(Process p, int maxLines) {
        StringBuilder sb = new StringBuilder();
        try (BufferedReader r = new BufferedReader(
                new InputStreamReader(p.getInputStream(), StandardCharsets.UTF_8))) {
            String line;
            int n = 0;
            while ((line = r.readLine()) != null && n++ < maxLines) {
                sb.append(line).append('\n');
            }
        } catch (IOException e) {
            Log.w(TAG, "lecture", e);
        }
        return sb.toString();
    }

    /** Dernieres lignes d'un fichier journal. */
    private static String tail(File file, int lines) {
        List<String> all = new ArrayList<>();
        try (BufferedReader r = new BufferedReader(
                new InputStreamReader(new java.io.FileInputStream(file), StandardCharsets.UTF_8))) {
            String line;
            while ((line = r.readLine()) != null) {
                all.add(line);
                if (all.size() > lines) all.remove(0);
            }
        } catch (IOException e) {
            return "(illisible : " + e.getMessage() + ")\n";
        }
        StringBuilder sb = new StringBuilder();
        for (String l : all) sb.append(l).append('\n');
        return sb.toString();
    }

    /**
     * Ce dont l'application a besoin de la fenetre qui affiche le rapport.
     * eviter une dependance a AndroidX.
     */
    interface AppCompatBridge {
        String appVersion();

        File gameLogFile();

        void deliver(Report report);
    }
}

