    print('clés:', list(d.keys()))
    for k, v in d.items():
        if isinstance(v, (str, int, float, type(None))):
            print('   %-14s = %r' % (k, (v[:120] if isinstance(v, str) else v)))
        elif isinstance(v, list):
            print('   %-14s : liste de %d' % (k, len(v)))
            if v:
                print('        0 ->', json.dumps(v[0], ensure_ascii=False)[:300])
        elif isinstance(v, dict):
            print('   %-14s : dict %s' % (k, list(v.keys())))
    print()
